mapper.update:
UPDATE sys_article SET quantity = CASE
WHEN id = #{article.id} THEN #{article.quantity}
END WHERE id IN
#{article.id}

mapper.select:
SELECT a.id, a.title, a.summary, a.cover, a.original_url, a.cover_image, a.is_stick, a.is_recommend, a.quantity, a.status, a.create_time, nsl.id AS notion_log_id, nsl.action AS notion_action, nsl.status AS notion_status, nsl.image_status AS notion_image_status, nsl.message AS notion_message, nsl.total_images AS notion_image_total, nsl.localized_images AS notion_image_localized, nsl.failed_images AS notion_image_failed, nsl.update_time AS notion_sync_time, c.name AS categoryName, u.nickname, u.avatar FROM sys_article a LEFT JOIN sys_category c ON a.category_id = c.id left join sys_user u on a.user_id = u.id LEFT JOIN notion_article_sync_log nsl ON nsl.id = ( SELECT nsl2.id FROM notion_article_sync_log nsl2 WHERE nsl2.article_id = a.id ORDER BY nsl2.id DESC LIMIT 1 )
a.status = #{query.status}
and a.title like concat('%',#{query.title},'%')
and a.category_id = #{query.categoryId}
AND a.id in (SELECT article_id FROM sys_article_tag WHERE tag_id = #{query.tagId})
order by a.is_stick desc, a.create_time desc

SELECT a.id, a.title, a.summary, a.cover, a.cover_image, a.content_md, a.quantity, a.is_stick, a.status, a.create_time, c.name AS categoryName, (SELECT COUNT(sc.id) FROM sys_comment sc WHERE sc.article_id = a.id) AS commentNum, (SELECT COUNT(sal.id) FROM sys_article_like sal WHERE sal.article_id = a.id) AS likeNum FROM sys_article a LEFT JOIN sys_category c ON a.category_id = c.id WHERE a.user_id = #{article.userId}
AND a.status = #{article.status}
AND a.title like concat('%',#{article.title},'%')
order by a.is_stick desc, a.create_time desc
